#[path = "solution.rs"]
mod solution;
use solution::*;

#[test]
fn parses_each_command_and_defaults() {
    assert_eq!(parse_invocation(&["create", "module", "core"]), Ok(Invocation {
        workspace: "data".into(),
        command: Command::Create { kind: Kind::Module, name: "core".into() },
    }));
    assert_eq!(parse_invocation(&["--workspace", "ops", "examine", "item"]), Ok(Invocation {
        workspace: "ops".into(), command: Command::Examine { name: "item".into() },
    }));
    assert_eq!(parse_invocation(&["send", "item", "--replace"]), Ok(Invocation {
        workspace: "data".into(), command: Command::Send { name: "item".into(), replace: true },
    }));
    assert_eq!(parse_invocation(&["check"]), Ok(Invocation {
        workspace: "data".into(), command: Command::Check { jobs: 1 },
    }));
}

#[test]
fn bundle_retains_tags_in_encounter_order_including_empty() {
    assert_eq!(parse_invocation(&["bundle", "pkg", "--tag", "a", "--optimized", "--tag", "", "--tag", "c"]), Ok(Invocation {
        workspace: "data".into(),
        command: Command::Bundle {
            name: "pkg".into(), optimized: true,
            tags: vec!["a".into(), "".into(), "c".into()],
        },
    }));
}

#[test]
fn jobs_boundaries_and_invalid_values_are_handled() {
    for (text, expected) in [("1", 1), ("256", 256)] {
        assert_eq!(parse_invocation(&["check", "--jobs", text]), Ok(Invocation {
            workspace: "data".into(), command: Command::Check { jobs: expected },
        }));
    }
    for text in ["0", "257", "abc", "-1"] {
        assert_eq!(parse_invocation(&["check", "--jobs", text]), Err(ParseError::InvalidValue {
            option: "--jobs".into(), value: text.into(),
        }));
    }
}

#[test]
fn missing_unknown_duplicate_and_unexpected_arguments_are_reported() {
    assert_eq!(parse_invocation(&[]), Err(ParseError::MissingCommand));
    assert_eq!(parse_invocation(&["unknown"]), Err(ParseError::UnknownCommand("unknown".into())));
    assert_eq!(parse_invocation(&["--workspace"]), Err(ParseError::MissingValue("--workspace".into())));
    assert_eq!(parse_invocation(&["bundle", "x", "--tag"]), Err(ParseError::MissingValue("--tag".into())));
    assert_eq!(parse_invocation(&["check", "--jobs"]), Err(ParseError::MissingValue("--jobs".into())));
    assert_eq!(parse_invocation(&["check", "--jobs", "2", "--jobs", "3"]), Err(ParseError::DuplicateOption("--jobs".into())));
    assert_eq!(parse_invocation(&["bundle", "x", "--optimized", "--optimized"]), Err(ParseError::DuplicateOption("--optimized".into())));
    assert_eq!(parse_invocation(&["examine", "x", "extra"]), Err(ParseError::Unexpected("extra".into())));
    assert_eq!(parse_invocation(&["examine", "x", "--workspace", "late"]), Err(ParseError::Unexpected("--workspace".into())));
}

#[test]
fn empty_workspace_and_name_are_invalid_without_mutating_args() {
    let args = ["--workspace", "", "send", "x"];
    let before = args;
    assert_eq!(parse_invocation(&args), Err(ParseError::InvalidValue {
        option: "--workspace".into(), value: "".into(),
    }));
    assert_eq!(args, before);
    assert_eq!(parse_invocation(&["examine", ""]), Err(ParseError::InvalidValue {
        option: "name".into(), value: "".into(),
    }));
}

